import 'package:flutter/material.dart';\r\nimport '../../core/theme/app_colors.dart';\r\nimport 'branch_list_screen.dart';\r\nimport 'my_appointments_screen.dart';\r\nimport 'service_history_screen.dart';\r\nimport 'profile_screen.dart';\r\n\r\n/// Main scaffold for the customer role with bottom navigation.\r\n///\r\n/// Tabs: Branches, Appointments, History, Profile\r\n/// Per PRD §5.1 — the customer's home experience.\r\nclass CustomerMainScaffold extends StatefulWidget {\r\n  const CustomerMainScaffold({super.key});\r\n\r\n  @override\r\n  State<CustomerMainScaffold> createState() => _CustomerMainScaffoldState();\r\n}\r\n\r\nclass _CustomerMainScaffoldState extends State<CustomerMainScaffold> {\r\n  int _currentIndex = 0;\r\n\r\n  final List<Widget> _pages = const [\r\n    BranchListScreen(),\r\n    MyAppointmentsScreen(),\r\n    ServiceHistoryScreen(),\r\n    ProfileScreen(),\r\n  ];\r\n\r\n  @override\r\n  Widget build(BuildContext context) {\r\n    return Scaffold(\r\n      body: IndexedStack(\r\n        index: _currentIndex,\r\n        children: _pages,\r\n      ),\r\n      bottomNavigationBar: NavigationBar(\r\n        selectedIndex: _currentIndex,\r\n        onDestinationSelected: (index) {\r\n          setState(() => _currentIndex = index);\r\n        },\r\n        destinations: const [\r\n          NavigationDestination(\r\n            icon: Icon(Icons.store_outlined),\r\n            selectedIcon: Icon(Icons.store),\r\n            label: 'Branches',\r\n          ),\r\n          NavigationDestination(\r\n            icon: Icon(Icons.calendar_today_outlined),\r\n            selectedIcon: Icon(Icons.calendar_today),\r\n            label: 'Appointments',\r\n          ),\r\n          NavigationDestination(\r\n            icon: Icon(Icons.history_outlined),\r\n            selectedIcon: Icon(Icons.history),\r\n            label: 'History',\r\n          ),\r\n          NavigationDestination(\r\n            icon: Icon(Icons.person_outline),\r\n            selectedIcon: Icon(Icons.person),\r\n            label: 'Profile',\r\n          ),\r\n        ],\r\n      ),\r\n    );\r\n  }\r\n}\r\n
